import React from 'react';

/**
 * ExecutionHistory - Shows recently executed programs
 */
const ExecutionHistory = ({ history, onSelectCode, isDarkMode }) => {
  if (!history || history.length === 0) {
    return (
      <div style={{
        padding: '1rem',
        backgroundColor: isDarkMode ? '#2d2d44' : '#ffffff',
        borderRadius: '8px',
        border: '2px solid var(--border-color)',
        marginTop: '1rem'
      }}>
        <p style={{ 
          color: 'var(--text-secondary)', 
          textAlign: 'center',
          fontStyle: 'italic'
        }}>
          No execution history yet. Run some code to see history!
        </p>
      </div>
    );
  }
  
  return (
    <div style={{
      padding: '1rem',
      backgroundColor: isDarkMode ? '#2d2d44' : '#ffffff',
      borderRadius: '8px',
      border: '2px solid var(--border-color)',
      marginTop: '1rem'
    }}>
      <h3 style={{
        marginBottom: '0.75rem',
        color: 'var(--text-primary)',
        fontSize: '1.1rem'
      }}>
        📜 Execution History
      </h3>
      
      <div style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '0.5rem'
      }}>
        {history.map((entry, index) => (
          <button
            key={index}
            onClick={() => onSelectCode(entry.fullCode)}
            style={{
              padding: '0.75rem 1rem',
              backgroundColor: entry.success 
                ? (isDarkMode ? 'rgba(158, 206, 106, 0.1)' : 'rgba(90, 143, 58, 0.1)')
                : (isDarkMode ? 'rgba(247, 118, 142, 0.1)' : 'rgba(214, 69, 80, 0.1)'),
              border: `2px solid ${entry.success ? 'var(--success-color)' : 'var(--error-color)'}`,
              borderRadius: '6px',
              cursor: 'pointer',
              transition: 'all 0.2s ease',
              textAlign: 'left'
            }}
            onMouseEnter={(e) => {
              e.target.style.transform = 'translateX(4px)';
            }}
            onMouseLeave={(e) => {
              e.target.style.transform = 'translateX(0)';
            }}
          >
            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: '0.25rem'
            }}>
              <span style={{
                fontWeight: '600',
                color: 'var(--text-primary)',
                fontSize: '0.9rem'
              }}>
                {entry.success ? '✅' : '❌'} {entry.code}
              </span>
              <span style={{
                fontSize: '0.75rem',
                color: 'var(--text-secondary)'
              }}>
                {entry.timestamp}
              </span>
            </div>
          </button>
        ))}
      </div>
      
      <p style={{
        marginTop: '0.75rem',
        fontSize: '0.85rem',
        color: 'var(--text-secondary)',
        fontStyle: 'italic'
      }}>
        💡 Click any entry to load that code back into the editor
      </p>
    </div>
  );
};

export default ExecutionHistory;
